package org.example.comp3820.domain.model;

/**
 * The deterministic half of a dashboard card.
 *
 * <p>Every field here is computed in Java from the patient's actual FHIR data — never
 * generated by the language model. The prose half of the card ({@code summary} and
 * {@code action}) is written by the AI agent afterwards, using these values as given facts.
 * Keeping the split at this boundary is what stops the model from inventing a step count or a
 * sleep duration, and it is what lets the thresholds be unit tested without a FHIR server or
 * an LLM in the loop.
 *
 * @param title        card heading, e.g. "Sleep"
 * @param fhirResource the FHIR resource type the figure came from, e.g. "Observation"
 * @param detail       the measured value in words, e.g. "6 h 10 min last night"
 * @param note         a short encouraging line, e.g. "A small change could help"
 * @param level        status and colour tone for the card
 */
public record RiskFactor(
        String title,
        String fhirResource,
        String detail,
        String note,
        RiskLevel level
) {
}
